+  it.each([new Date(NaN), '2000-01-01T00:00Z', 0, null, {}, { getTime: (): number => 0 }])('requires a finite actual Date (%j)', (instant) => {
+    expect(() => localDateContainsUtc('2000-01-01', instant as Date, 'UTC')).toThrow(message);
+  });
