+    }
+  }
+
+  const flags: LocalTimeResolution['flags'] = [];
+  let chosen: { utcMs: number; offset: number };
+
+  if (matches.length === 1) {
+    chosen = matches[0];
+  } else if (matches.length > 1) {
+    // Fold: two readings of the same wall clock — take the earlier.
